import React from "react";
import { useFreeCellGame } from "../hooks/useFreeCellGame";
import Card from "./Card";
import "../FreeCell.css";
import { useWindowSize } from 'react-use'
import Confetti from 'react-confetti'

const FreeCellBoard: React.FC = () => {
  const {
    gameState,
    selectCard,
    getCardKey,
    undo,
    canUndo,
  } = useFreeCellGame();

  const handleDrop = (e: React.DragEvent, destination: any) => {
    e.preventDefault();
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const { width, height } = useWindowSize();

  const gameFinished = gameState?.foundations?.every(f => f?.length === 13)

  console.log(gameState, 'gameState')
  return (
    <div className="board">
      {gameFinished ? <div style={{ position: 'absolute', top: -105, left: -280 }}><Confetti
        width={width}
        height={height}
        drawShape={ctx => {
          const scale = 1.5;
          ctx.beginPath();
          ctx.moveTo(14 * scale, -19 * scale);
          ctx.bezierCurveTo(23 * scale, -12 * scale, 19 * scale, 0, 14 * scale, -12 * scale);
          ctx.bezierCurveTo(9 * scale, 0, 5 * scale, -12 * scale, 14 * scale, -19 * scale);
          ctx.bezierCurveTo(18 * scale, -23 * scale, 10 * scale, -25 * scale, 14 * scale, -27 * scale);
          ctx.stroke();
          ctx.closePath();
        }}
        gravity={-0.05}
        confettiSource={{ x: 0, y: height, w: width, h: 0 }}
        initialVelocityY={4}
      /></div> : null}
      <div className="top-row">
        {/* Free Cells */}
        <div className="free-cells-section">
          <h3>Free Cells</h3>
          <div className="flex-row">
            {gameState.freeCells.map((card, index) => (
              <div
                key={index}
                className="free-cell"
                onClick={() => {
                  if (card) {
                    selectCard({ type: "freeCell", index });
                  }
                }}
                onDrop={(e) => handleDrop(e, { type: "freeCell", index })}
                onDragOver={handleDragOver}
              >
                {card ? (
                  <Card
                    card={card}
                    isDraggable={true}
                    isSelected={false}
                    onClick={(e) => {
                      e?.stopPropagation();
                      selectCard({ type: "freeCell", index });
                    }}
                  />
                ) : (
                  <div className="empty-cell">Empty</div>
                )}
              </div>
            ))}
          </div>
        </div>
        <div className="controls">
          <button
            className="undo-button"
            onClick={undo}
            disabled={!canUndo()}
          >
            ↶ Undo
          </button>
        </div>
        {/* Foundations */}
        <div className="foundations-section">
          <h3>Foundations</h3>
          <div className="flex-row">
            {gameState.foundations.map((foundation, index) => (
              <div
                key={index}
                className="foundation"
                onDrop={(e) => handleDrop(e, { type: "foundation", index })}
                onDragOver={handleDragOver}
              >
                {foundation.length > 0 ? (
                  <Card card={foundation[foundation.length - 1]} />
                ) : (
                  <div className="empty-foundation">
                    {["♥", "♦", "♣", "♠"][index]}
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Tableau */}
      <div className="tableau">
        {gameState.tableau.map((pile, pileIndex) => (
          <div
            key={pileIndex}
            className="pile"
            onDrop={(e) => handleDrop(e, { type: "tableau", index: pileIndex })}
            onDragOver={handleDragOver}
          >
            {pile.length === 0 ? (
              <div className="empty-pile">Empty</div>
            ) : (
              pile.map((card, cardIndex) => {
                return (
                  <Card
                    key={`${getCardKey(card)}-${pileIndex}-${cardIndex}`}
                    card={card}
                    isDraggable={true}
                    isSelected={false}
                    onClick={(e) => {
                      e?.stopPropagation();
                      // Pass the cardIndex so we know where in the pile to start the sequence
                      selectCard({ type: "tableau", index: pileIndex }, cardIndex);
                    }}
                    style={{ marginTop: cardIndex > 0 ? "-70px" : "0" }}
                  />
                );
              })
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default FreeCellBoard;