import { useState, useEffect, useRef } from "react";
import { createDeck, shuffleDeck } from "../models/Deck";
import { Card } from "../models/Card";

type Pile = Card[];

interface GameState {
  tableau: Pile[];
  freeCells: (Card | null)[];
  foundations: Pile[];
}

type MoveSource =
  | { type: "tableau"; index: number }
  | { type: "freeCell"; index: number }
  | { type: "foundation"; index: number };

type MoveDestination =
  | { type: "tableau"; index: number }
  | { type: "freeCell"; index: number }
  | { type: "foundation"; index: number };

export const useFreeCellGame = () => {
  const [gameState, setGameState] = useState<GameState>(() => {
    const deck = shuffleDeck(createDeck());
    const tableau: Pile[] = Array.from({ length: 8 }, () => []);
    const freeCells: (Card | null)[] = Array(4).fill(null);
    const foundations: Pile[] = Array.from({ length: 4 }, () => []);

    // Deal cards to tableau
    let cardIndex = 0;
    for (let col = 0; col < 8; col++) {
      const cardsInColumn = col < 4 ? 7 : 6;
      for (let row = 0; row < cardsInColumn; row++) {
        if (deck[cardIndex]) {
          tableau[col].push(deck[cardIndex]);
          cardIndex++;
        }
      }
    }

    return { tableau, freeCells, foundations };
  });

  const [selectedCard, setSelectedCard] = useState<{
    source: MoveSource;
    cardKey: string;
  } | null>(null);
  const [lastAutoMoveIndex, setLastAutoMoveIndex] = useState<number>(-1);
  const [history, setHistory] = useState<GameState[]>([]);
  const [isAutoMoving, setIsAutoMoving] = useState(false);
  const autoMoveTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  // Helper functions
  const isRed = (card: Card): boolean =>
    card.suit === "Hearts" || card.suit === "Diamonds";

  const getCardKey = (card: Card): string =>
    `${card.suit}-${card.rank}`;

  const canPlaceOnTableau = (card: Card, pile: Pile): boolean => {
    if (pile.length === 0) return true;

    const topCard = pile[pile.length - 1];
    return (
      isRed(card) !== isRed(topCard) &&
      card.rank === topCard.rank - 1
    );
  };

  const canPlaceOnFoundation = (card: Card, foundation: Pile): boolean => {
    if (foundation.length === 0) {
      return card.rank === 1;
    }

    const topCard = foundation[foundation.length - 1];
    return (
      card.suit === topCard.suit &&
      card.rank === topCard.rank + 1
    );
  };

  const getCard = (source: MoveSource): Card | null => {
    if (source.type === "tableau") {
      const pile = gameState.tableau[source.index];
      return pile.length > 0 ? pile[pile.length - 1] : null;
    } else if (source.type === "freeCell") {
      return gameState.freeCells[source.index];
    } else if (source.type === "foundation") {
      const pile = gameState.foundations[source.index];
      return pile.length > 0 ? pile[pile.length - 1] : null;
    }
    return null;
  };

  const getCardAtIndex = (pileIndex: number, cardIndex: number): Card | null => {
    const pile = gameState.tableau[pileIndex];
    if (cardIndex < 0 || cardIndex >= pile.length) return null;
    return pile[cardIndex];
  };

  // Count free cells and empty tableau columns
  const countFreeResources = (excludeTableauIndex?: number): { freeCells: number; emptyColumns: number } => {
    const freeCells = gameState.freeCells.filter(cell => cell === null).length;
    const emptyColumns = gameState.tableau.filter((pile, idx) =>
      pile.length === 0 && idx !== excludeTableauIndex
    ).length;

    return { freeCells, emptyColumns };
  };

  // Calculate max movable cards: (1 + free cells) * 2^(empty columns)
  const getMaxMovableCards = (excludeTableauIndex?: number): number => {
    const { freeCells, emptyColumns } = countFreeResources(excludeTableauIndex);
    return (1 + freeCells) * Math.pow(2, emptyColumns);
  };

  // Check if a sequence of cards is valid (alternating colors, descending ranks)
  const isValidSequence = (cards: Card[]): boolean => {
    for (let i = 0; i < cards.length - 1; i++) {
      const current = cards[i];
      const next = cards[i + 1];

      if (isRed(current) === isRed(next)) return false; // Must alternate colors
      if (current.rank !== next.rank + 1) return false; // Must be descending
    }
    return true;
  };

  // Get the movable sequence from a tableau pile starting at cardIndex
  const getMovableSequence = (pileIndex: number, cardIndex: number): Card[] => {
    const pile = gameState.tableau[pileIndex];
    if (cardIndex >= pile.length) return [];

    const sequence = pile.slice(cardIndex);

    // Check if it's a valid sequence
    if (!isValidSequence(sequence)) return [];

    // Check if we have enough free resources to move it
    const maxMovable = getMaxMovableCards(pileIndex);
    if (sequence.length > maxMovable) return [];

    return sequence;
  };

  const removeCard = (source: MoveSource, state: GameState): GameState => {
    const newState = { ...state };

    if (source.type === "tableau") {
      newState.tableau = [...state.tableau];
      newState.tableau[source.index] = [...state.tableau[source.index]];
      newState.tableau[source.index].pop();
    } else if (source.type === "freeCell") {
      newState.freeCells = [...state.freeCells];
      newState.freeCells[source.index] = null;
    } else if (source.type === "foundation") {
      newState.foundations = [...state.foundations];
      newState.foundations[source.index] = [...state.foundations[source.index]];
      newState.foundations[source.index].pop();
    }

    return newState;
  };

  const removeSequence = (pileIndex: number, cardIndex: number, state: GameState): GameState => {
    const newState = { ...state };
    newState.tableau = [...state.tableau];
    newState.tableau[pileIndex] = [...state.tableau[pileIndex].slice(0, cardIndex)];
    return newState;
  };

  const addCard = (card: Card, destination: MoveDestination, state: GameState): GameState => {
    const newState = { ...state };

    if (destination.type === "tableau") {
      newState.tableau = [...state.tableau];
      newState.tableau[destination.index] = [...state.tableau[destination.index], card];
    } else if (destination.type === "freeCell") {
      newState.freeCells = [...state.freeCells];
      newState.freeCells[destination.index] = card;
    } else if (destination.type === "foundation") {
      newState.foundations = [...state.foundations];
      newState.foundations[destination.index] = [...state.foundations[destination.index], card];
    }

    return newState;
  };

  const addSequence = (cards: Card[], destination: MoveDestination, state: GameState): GameState => {
    let newState = state;
    for (const card of cards) {
      newState = addCard(card, destination, newState);
    }
    return newState;
  };

  const isValidMove = (source: MoveSource, destination: MoveDestination): boolean => {
    const card = getCard(source);
    if (!card) return false;

    if (source.type === destination.type && source.index === destination.index) {
      return false;
    }

    if (destination.type === "tableau") {
      return canPlaceOnTableau(card, gameState.tableau[destination.index]);
    } else if (destination.type === "freeCell") {
      if (source.type === "freeCell") return false;
      return gameState.freeCells[destination.index] === null;
    } else if (destination.type === "foundation") {
      const foundationIndex = gameState.foundations.findIndex(
        f => f.length > 0 && f[0].suit === card.suit
      );

      if (foundationIndex !== -1) {
        return foundationIndex === destination.index &&
          canPlaceOnFoundation(card, gameState.foundations[foundationIndex]);
      } else {
        return card.rank === 1 && gameState.foundations[destination.index].length === 0;
      }
    }

    return false;
  };

  const getAllValidMoves = (source: MoveSource): MoveDestination[] => {
    const validMoves: MoveDestination[] = [];
    const card = getCard(source);
    if (!card) return validMoves;

    // Priority 1: Foundations (MOST IMPORTANT)
    for (let i = 0; i < 4; i++) {
      const destination: MoveDestination = { type: "foundation", index: i };
      if (isValidMove(source, destination)) {
        validMoves.push(destination);
      }
    }

    // Priority 2: Tableau (cascades) - non-empty piles
    for (let i = 0; i < 8; i++) {
      if (source.type === "tableau" && source.index === i) continue;
      const destination: MoveDestination = { type: "tableau", index: i };
      if (isValidMove(source, destination)) {
        if (gameState.tableau[i].length > 0) {
          validMoves.push(destination);
        }
      }
    }

    // Priority 3: Empty tableau spaces
    for (let i = 0; i < 8; i++) {
      if (source.type === "tableau" && source.index === i) continue;
      const destination: MoveDestination = { type: "tableau", index: i };
      if (isValidMove(source, destination) && gameState.tableau[i].length === 0) {
        validMoves.push(destination);
      }
    }

    // Priority 4: Free cells (only if source is not already a free cell)
    if (source.type !== "freeCell") {
      for (let i = 0; i < 4; i++) {
        const destination: MoveDestination = { type: "freeCell", index: i };
        if (isValidMove(source, destination)) {
          validMoves.push(destination);
        }
      }
    }

    return validMoves;
  };

  const getAllValidMovesForSequence = (pileIndex: number, cardIndex: number): MoveDestination[] => {
    const validMoves: MoveDestination[] = [];
    const sequence = getMovableSequence(pileIndex, cardIndex);

    if (sequence.length === 0) return validMoves;

    const firstCard = sequence[0];

    // Only tableau destinations are valid for sequences
    for (let i = 0; i < 8; i++) {
      if (pileIndex === i) continue;
      if (canPlaceOnTableau(firstCard, gameState.tableau[i])) {
        // Prioritize non-empty piles
        if (gameState.tableau[i].length > 0) {
          validMoves.push({ type: "tableau", index: i });
        }
      }
    }

    // Then empty piles
    for (let i = 0; i < 8; i++) {
      if (pileIndex === i) continue;
      if (gameState.tableau[i].length === 0) {
        validMoves.push({ type: "tableau", index: i });
      }
    }

    return validMoves;
  };

  // Find one card that can move to foundation
  const findNextAutoMove = (state: GameState): { source: MoveSource; destination: MoveDestination } | null => {
    // Check all tableau piles
    for (let i = 0; i < 8; i++) {
      const pile = state.tableau[i];
      if (pile.length === 0) continue;

      const card = pile[pile.length - 1];

      // Check if this card can go to any foundation
      for (let j = 0; j < 4; j++) {
        const foundation = state.foundations[j];

        if (canPlaceOnFoundation(card, foundation)) {
          return {
            source: { type: "tableau", index: i },
            destination: { type: "foundation", index: j }
          };
        }
      }
    }

    // Check all free cells
    for (let i = 0; i < 4; i++) {
      const card = state.freeCells[i];
      if (!card) continue;

      // Check if this card can go to any foundation
      for (let j = 0; j < 4; j++) {
        const foundation = state.foundations[j];

        if (canPlaceOnFoundation(card, foundation)) {
          return {
            source: { type: "freeCell", index: i },
            destination: { type: "foundation", index: j }
          };
        }
      }
    }

    return null;
  };

  // Auto-move one card at a time with delay
  const startAutoMoveSequence = (state: GameState) => {
    if (isAutoMoving) return;

    setIsAutoMoving(true);

    const performNextMove = (currentState: GameState) => {
      const nextMove = findNextAutoMove(currentState);

      if (!nextMove) {
        setIsAutoMoving(false);
        return;
      }

      const card = nextMove.source.type === "tableau"
        ? currentState.tableau[nextMove.source.index][currentState.tableau[nextMove.source.index].length - 1]
        : currentState.freeCells[nextMove.source.index];

      if (!card) {
        setIsAutoMoving(false);
        return;
      }

      let newState = removeCard(nextMove.source, currentState);
      newState = addCard(card, nextMove.destination, newState);

      setGameState(newState);

      // Schedule next move
      autoMoveTimeoutRef.current = setTimeout(() => {
        performNextMove(newState);
      }, 250);
    };

    performNextMove(state);
  };

  // Cleanup timeout on unmount
  useEffect(() => {
    return () => {
      if (autoMoveTimeoutRef.current) {
        clearTimeout(autoMoveTimeoutRef.current);
      }
    };
  }, []);

  const moveCard = (source: MoveSource, destination: MoveDestination): boolean => {
    if (!isValidMove(source, destination)) return false;

    const card = getCard(source);
    if (!card) return false;

    setHistory(prev => [...prev, gameState]);

    let newState = removeCard(source, gameState);
    newState = addCard(card, destination, newState);

    setGameState(newState);
    setSelectedCard(null);
    setLastAutoMoveIndex(-1);

    // Start auto-move sequence after a short delay
    setTimeout(() => startAutoMoveSequence(newState), 100);

    return true;
  };

  const moveSequence = (pileIndex: number, cardIndex: number, destination: MoveDestination): boolean => {
    if (destination.type !== "tableau") return false;

    const sequence = getMovableSequence(pileIndex, cardIndex);
    if (sequence.length === 0) return false;

    const firstCard = sequence[0];
    if (!canPlaceOnTableau(firstCard, gameState.tableau[destination.index])) return false;

    setHistory(prev => [...prev, gameState]);

    let newState = removeSequence(pileIndex, cardIndex, gameState);
    newState = addSequence(sequence, destination, newState);

    setGameState(newState);
    setSelectedCard(null);
    setLastAutoMoveIndex(-1);

    // Start auto-move sequence after a short delay
    setTimeout(() => startAutoMoveSequence(newState), 100);

    return true;
  };

  const undo = () => {
    if (history.length === 0) return;

    // Cancel any ongoing auto-moves
    if (autoMoveTimeoutRef.current) {
      clearTimeout(autoMoveTimeoutRef.current);
      autoMoveTimeoutRef.current = null;
    }
    setIsAutoMoving(false);

    const previousState = history[history.length - 1];
    setGameState(previousState);
    setHistory(prev => prev.slice(0, -1));
    setSelectedCard(null);
    setLastAutoMoveIndex(-1);
  };

  const canUndo = (): boolean => {
    return history.length > 0 && !isAutoMoving;
  };

  const selectCard = (source: MoveSource, cardIndexInPile?: number) => {
    if (isAutoMoving) return; // Don't allow moves during auto-move

    let card: Card | null = null;
    let cardKey: string;
    let isSequenceMove = false;

    // Determine if this is a sequence move (clicking a card that's not the last one)
    if (source.type === "tableau" && cardIndexInPile !== undefined) {
      const pile = gameState.tableau[source.index];
      card = getCardAtIndex(source.index, cardIndexInPile);
      if (!card) return;
      cardKey = getCardKey(card);

      // It's a sequence move if the card is not the last card in the pile
      isSequenceMove = cardIndexInPile < pile.length - 1;
    } else {
      card = getCard(source);
      if (!card) return;
      cardKey = getCardKey(card);
      isSequenceMove = false;
    }

    const isSameCard = selectedCard?.source.type === source.type &&
      selectedCard?.source.index === source.index &&
      selectedCard?.cardKey === cardKey;

    if (isSameCard) {
      // Get valid moves based on whether it's a sequence or single card
      const validMoves = isSequenceMove
        ? getAllValidMovesForSequence(source.index, cardIndexInPile!)
        : getAllValidMoves(source);

      if (validMoves.length === 0) {
        setSelectedCard(null);
        setLastAutoMoveIndex(-1);
        return;
      }

      const nextIndex = (lastAutoMoveIndex + 1) % validMoves.length;
      const nextMove = validMoves[nextIndex];

      // If moving a sequence from tableau
      if (isSequenceMove) {
        moveSequence(source.index, cardIndexInPile!, nextMove);
      } else {
        moveCard(source, nextMove);
      }

      setLastAutoMoveIndex(nextIndex);
      return;
    }

    // New card selected - get valid moves
    const validMoves = isSequenceMove
      ? getAllValidMovesForSequence(source.index, cardIndexInPile!)
      : getAllValidMoves(source);

    if (validMoves.length === 1) {
      // If moving a sequence from tableau
      if (isSequenceMove) {
        const success = moveSequence(source.index, cardIndexInPile!, validMoves[0]);
        if (success) {
          setLastAutoMoveIndex(0);
        }
      } else {
        moveCard(source, validMoves[0]);
        setLastAutoMoveIndex(0);
      }
    } else if (validMoves.length > 1) {
      // If moving a sequence from tableau
      if (isSequenceMove) {
        const success = moveSequence(source.index, cardIndexInPile!, validMoves[0]);
        if (success) {
          setSelectedCard({ source, cardKey });
          setLastAutoMoveIndex(0);
        }
      } else {
        moveCard(source, validMoves[0]);
        setSelectedCard({ source, cardKey });
        setLastAutoMoveIndex(0);
      }
    } else {
      setSelectedCard({ source, cardKey });
      setLastAutoMoveIndex(-1);
    }
  };

  const autoMoveToFoundation = (source: MoveSource): boolean => {
    const card = getCard(source);
    if (!card) return false;

    for (let i = 0; i < 4; i++) {
      const destination: MoveDestination = { type: "foundation", index: i };
      if (isValidMove(source, destination)) {
        moveCard(source, destination);
        return true;
      }
    }
    return false;
  };

  return {
    gameState,
    selectedCard,
    moveCard,
    selectCard,
    isValidMove,
    autoMoveToFoundation,
    setSelectedCard,
    getAllValidMoves,
    getCardKey,
    undo,
    canUndo,
    getMaxMovableCards,
    getMovableSequence,
    isAutoMoving,
  };
};