import React from "react";
import { Card as CardModel, rankNames } from "../models/Card";

interface CardProps {
  card: CardModel;
  onClick?: (e?: React.MouseEvent) => void;
  isDraggable?: boolean;
  isSelected?: boolean;
  style?: React.CSSProperties;
}

const Card: React.FC<CardProps> = ({
  card,
  onClick,
  isDraggable = false,
  isSelected = false,
  style
}) => {
  const isRed = card.suit === "Hearts" || card.suit === "Diamonds";

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.effectAllowed = "move";
    e.dataTransfer.setData("text/plain", JSON.stringify(card));
  };

  return (
    <div
      className={`card ${isRed ? "red" : "black"} ${isSelected ? "selected" : ""}`}
      onClick={onClick}
      draggable={isDraggable}
      onDragStart={handleDragStart}
      style={style}
    >
      <div className="card-content">
        <span className="rank">  <span className="suit">{card.suit === "Hearts" ? "♥" : card.suit === "Diamonds" ? "♦" : card.suit === "Clubs" ? "♣" : "♠"}</span>
          {" "}{rankNames[card.rank - 1]}</span>
        <span className="suit"><span className="rank">{rankNames[card.rank - 1]}</span>{" "}{card.suit === "Hearts" ? "♥" : card.suit === "Diamonds" ? "♦" : card.suit === "Clubs" ? "♣" : "♠"}</span>
      </div>
    </div>
  );
};

export default Card;